1-// WHAT THIS MOUNT HOLDS — the engine version a repo has installed, and the version
2-// of each pack it has installed, read out of and written back into its settings
3-// file. One module, because the update flows, the install flow, the vendor writer
4-// and the migration selector all ask the same question of the same file, and four
5-// spellings of "where does the version live" is how a member ends up priced by one
6-// and converged by another.
7-//
8-// WHERE THEY LIVE (#1252). The engine version is the top-level `engineVersion`. A
9-// pack's version is `version` ON THAT PACK'S OWN ENTRY — the one place it cannot
10:// outlive what it prices: the central `claudinite.packVersions` map it replaces was
11-// keyed by a pack id nothing else in the file had to agree with, so a rename left a
12-// version priced against a pack the declaration no longer named.
13-//
14-// THE LEGACY BLOCK IS READ, NEVER WRITTEN. A member reaches the record that reshapes
15-// its file one converge AFTER the engine that can read the new shape, so every read
16-// here falls back to `claudinite` and every write leaves it exactly as it found it —
17-// the reshape is the record's single job, not something four writers do a bit of.
18-import { canonicalPackVersions } from './pack_loader/renamed-packs.mjs';
19-// `isVersion`, not `isDeclaredVersion`: the install floor (0) is a real state for a
20-// version a repo HAS — "below everything" — even though nothing may DECLARE it as a
21-// manifest's or a release's own number.
22-import { isVersion } from './version.mjs';
23-
24-// The retired block. Named so the readers below and the #1252 record agree on the
25-// one spelling, and so Phase 3 has a symbol to grep for when it deletes the
26-// tolerance.
27-export const LEGACY_STAMP_KEY = 'claudinite';
28-
29:// `{ engineVersion, packVersions }` for a parsed settings object — the shape every
30-// caller already passes around as `installed`. Null versions rather than absent
31-// keys: "not installed" is a state of its own, and a caller comparing against a
32-// zero or an empty string would read a fresh mount as ancient.
33-export function installedVersions(raw) {
34-  const legacy = raw?.[LEGACY_STAMP_KEY] ?? null;
35-  const engineVersion = isVersion(raw?.engineVersion) ? raw.engineVersion
36-    : (isVersion(legacy?.engineVersion) ? legacy.engineVersion : null);
37-
38:  const packVersions = {};
39:  const legacyPacks = legacy?.packVersions;
40-  if (legacyPacks && typeof legacyPacks === 'object' && !Array.isArray(legacyPacks)) {
41:    Object.assign(packVersions, canonicalPackVersions(legacyPacks));
42-  }
43-  for (const entry of Array.isArray(raw?.packs) ? raw.packs : []) {
44-    if (entry && typeof entry === 'object' && typeof entry.id === 'string' && isVersion(entry.version)) {
45:      packVersions[entry.id] = entry.version;
46-    }
47-  }
48:  return { engineVersion, packVersions };
49-}
50-
51-// Has this repo been vendored at all? A mount that has never run stamps neither
52-// number, and every caller that used to ask "is there a stamp" is asking this.
53-export const hasInstalledMount = (raw) => {
54:  const { engineVersion, packVersions } = installedVersions(raw);
55:  return engineVersion !== null || Object.keys(packVersions).length > 0;
56-};
57-
58-// The settings object with these versions recorded: `engineVersion` at the top,
59-// each pack's version on its own entry. Returned rather than written, so the caller
60-// that owns the file owns the write — and so this stays testable without one.
61-//
62-// A version for a pack the declaration does not carry is DROPPED, not appended as
63-// a bare entry: an entry is a declaration that the pack is active, and inventing
64-// one here would activate a pack nobody declared. A pack entry declared as a plain
65-// string is widened to an object so it can hold its version; every other property
66-// and the entry ORDER survive untouched, because this file is one a person reads.
67:export function withInstalledVersions(raw, { engineVersion, packVersions } = {}) {
68-  const next = { ...(raw && typeof raw === 'object' && !Array.isArray(raw) ? raw : {}) };
69-  if (engineVersion !== undefined && engineVersion !== null) next.engineVersion = engineVersion;
70-
71:  if (packVersions) {
72-    next.packs = (Array.isArray(next.packs) ? next.packs : []).map((entry) => {
73-      const id = typeof entry === 'string' ? entry : entry?.id;
74:      if (typeof id !== 'string' || !Object.hasOwn(packVersions, id)) return entry;
75-      const base = typeof entry === 'string' ? { id: entry } : { ...entry };
76-      // `version` sits directly after `id`, where a reader scanning the list for a
77-      // pack's version finds it beside the name rather than past its config. The
78-      // entry's OWN `version` is destructured out before the spread, not merely
79-      // overwritten by key order: leaving it in `rest` puts the stale number back
80-      // after the new one and freezes every member at the version it already had.
81-      const { id: entryId, version: _prior, ...rest } = base;
82:      return { id: entryId, version: packVersions[id], ...rest };
83-    });
84-  }
85-  return next;
86-}

